import type { KnowledgeCourse } from "./knowledge";

type LessonSeed = { title: string; summary: string; content: string; objectives: string[]; question: string; options: string[]; answer: number; explanation: string };
type Seed = { id: string; title: string; subject: string; description: string; cost: number; lessons: LessonSeed[] };
const lesson = (title:string, summary:string, content:string, objectives:string[], question:string, options:string[], answer:number, explanation:string):LessonSeed => ({title,summary,content,objectives,question,options,answer,explanation});

const seeds: Seed[] = [
{id:"universal-science",title:"Science & the Natural World",subject:"Science",description:"Scientific reasoning, physics, chemistry, biology, Earth science and astronomy.",cost:0,lessons:[
lesson("How science builds knowledge","Scientific questions, hypotheses, experiments and evidence.","Science is a disciplined way to investigate the natural world. A useful question is specific enough to investigate and asks about observable or measurable phenomena. A hypothesis is a testable proposed explanation; it is not simply a guess. A prediction states what should be observed if the hypothesis is supported.\n\nA fair test changes an independent variable, measures a dependent variable and controls other relevant factors. Repeated trials help reveal variation. Measurements should include units, and conclusions must match the quality and limits of the evidence. Correlation alone does not prove causation. Scientific explanations remain open to revision when stronger evidence appears.",["Distinguish question, hypothesis, prediction and conclusion","Identify variables and controls","Explain why repeatability and evidence matter"],"In a fair experiment, what should happen to the variables?",["Change several factors together","Change one independent variable while controlling relevant factors","Choose results that support the hypothesis","Avoid repeating measurements"],1,"Changing one factor while controlling others makes it easier to identify what caused an observed effect.") ,
lesson("Matter, atoms and chemical change","The particle model, atomic structure, bonding and reactions.","Matter has mass and occupies space. In the particle model, solids have particles close together that mainly vibrate, liquids have particles that remain close but move past one another, and gases have particles far apart with rapid random motion. Temperature relates to average particle kinetic energy.\n\nAtoms contain protons and neutrons in a nucleus with electrons around it. The atomic number identifies an element. Chemical bonds arise from interactions involving electrons: ionic bonding involves electron transfer and attraction between ions; covalent bonding involves shared electron pairs; metallic bonding involves delocalised electrons. In a chemical reaction atoms are rearranged, so mass is conserved in a closed system.",["Use the particle model to explain states of matter","Relate atomic number to element identity","Distinguish ionic, covalent and metallic bonding"],"What is conserved when a chemical reaction occurs in a closed system?",["The number and types of atoms","The arrangement of all particles","The temperature","The physical state"],0,"Chemical reactions rearrange atoms; they do not create or destroy them in ordinary chemical processes.") ,
lesson("Forces, energy and motion","Newtonian motion, work, energy transfer and conservation.","A force is an interaction that can change an object's motion or shape. The resultant force is the vector sum of forces. If the resultant force is zero, velocity remains constant; if it is non-zero, acceleration occurs. Newton's second law expresses this as F = ma for constant mass. Weight is the gravitational force on a mass and differs from mass itself.\n\nEnergy is transferred between stores, for example by heating, mechanical work, electrical work or radiation. Kinetic energy depends on mass and speed; gravitational potential energy near Earth's surface depends on mass, gravitational field strength and height. Energy is conserved overall, although some becomes dispersed to the surroundings and less useful for a chosen task.",["Distinguish mass, weight, force and resultant force","Apply F = ma conceptually","Describe energy stores, transfers and dissipation"],"If the resultant force on an object is zero, what can be said?",["It must be stationary","Its velocity is constant","It must be accelerating","Its mass is zero"],1,"Zero resultant force means zero acceleration, so the object's velocity remains constant.") ,
lesson("Living systems, evolution and ecosystems","Cells, inheritance, natural selection and ecological relationships.","Cells are the basic structural and functional units of life. Cell membranes regulate exchange; genetic information is stored in DNA. In multicellular organisms, specialised cells form tissues, organs and organ systems. Photosynthesis transfers light energy into chemical energy stored in organic molecules; cellular respiration releases usable energy from these molecules.\n\nEvolution describes changes in heritable characteristics of populations across generations. Natural selection occurs when inherited variation affects survival or reproductive success in a particular environment. Ecosystems connect organisms with one another and with non-living conditions. Energy flows through food webs while nutrients are recycled; changes to one population can affect many others.",["Describe organisation from cells to organ systems","Explain natural selection using variation and inheritance","Interpret food chains and ecosystem interactions"],"Natural selection acts directly on which level?",["Individual inherited traits affecting reproductive success","A species choosing to evolve","An organism changing its genes because it needs to","The ecosystem deciding which species survive"],0,"Individuals with heritable traits that improve reproductive success tend to leave more offspring, changing populations over generations.")
]},
{id:"universal-mathematics",title:"Mathematics & Logical Reasoning",subject:"Mathematics",description:"Number sense, algebra, geometry, probability, statistics and mathematical modelling.",cost:0,lessons:[
lesson("Number sense, ratios and proportionality","Fractions, percentages, rates, units and estimation.","Numbers describe quantities and relationships. Fractions represent parts of a whole or quotients; equivalent fractions have the same value even when written differently. A percentage is a ratio per hundred. To find p percent of a quantity, multiply by p/100. Percentage change uses the original value as the reference: change divided by original, multiplied by 100.\n\nA ratio compares quantities and should be simplified by dividing each part by the same non-zero factor. A rate compares quantities with different units, such as kilometres per hour. Unit conversion requires multiplying by a conversion factor equal to one. Estimate before calculating: an approximate answer helps detect misplaced decimals and unreasonable results.",["Convert between fractions, decimals and percentages","Solve ratio and rate problems","Use units and estimation to check results"],"A price rises from ₹200 to ₹250. What is the percentage increase?",["20%","25%","50%","Not enough information"],1,"The increase is ₹50; 50/200 × 100 = 25%.") ,
lesson("Algebra and equations","Variables, expressions, equations, inequalities and rearrangement.","Algebra uses symbols to represent numbers and general relationships. An expression such as 3x + 5 has a value once x is known; an equation states that two expressions are equal. To solve an equation, perform the same valid operation on both sides so equality is preserved.\n\nCollect like terms, use the distributive property and reverse operations carefully. For example, 3x + 5 = 20 gives 3x = 15 and x = 5. Substitution checks the result. Inequalities describe ranges; multiplying or dividing both sides by a negative number reverses the inequality sign. Rearranging formulae is the same balance principle applied to a named relationship.",["Simplify expressions using algebraic laws","Solve linear equations and inequalities","Check solutions by substitution"],"Solve 4x − 7 = 9.",["x = 2","x = 4","x = 8","x = 16"],1,"Adding 7 gives 4x = 16; dividing by 4 gives x = 4.") ,
lesson("Functions, graphs and mathematical models","Inputs, outputs, slope, intercepts and model assumptions.","A function assigns exactly one output to each permitted input. The notation f(x) names the output for input x. A linear function has the form y = mx + c: m is the slope or rate of change and c is the vertical intercept. A graph makes patterns, trends and intersections visible.\n\nA mathematical model simplifies a real situation using variables and assumptions. For example, a fixed fee plus a cost per kilometre can be represented by y = mx + c. Interpret slope and intercept in context and check whether the model is sensible outside the observed range. A good model is not merely a curve that fits data; it should also have meaningful assumptions and acknowledge uncertainty.",["Interpret function notation and domain","Explain slope and intercept in context","Evaluate assumptions and limits of a model"],"In y = 5x + 12, what does 5 represent?",["The output when x is zero","The rate of change of y per unit increase in x","The domain","The maximum possible value"],1,"The coefficient of x is the slope: y increases by 5 for each unit increase in x.") ,
lesson("Geometry, probability and data","Shape, proof, chance, sampling and statistical interpretation.","Geometry studies properties of shapes, distances and angles. Area measures a two-dimensional region; volume measures three-dimensional space. Similar shapes preserve angles and have proportional corresponding lengths. A mathematical proof uses definitions, known results and logically connected steps rather than a few confirming examples.\n\nProbability ranges from 0 to 1 and quantifies uncertainty under a stated model. For equally likely outcomes, probability is favourable outcomes divided by total outcomes. Statistics summarises data using measures such as mean, median, range and spread. Samples should represent the population; biased sampling and confusing correlation with causation can lead to misleading conclusions.",["Choose appropriate geometric measures","Calculate simple probabilities","Recognise sampling bias and misleading statistics"],"Why is a representative sample important?",["It guarantees the result wanted","It reduces systematic distortion when estimating a population","It makes every value identical","It removes all uncertainty"],1,"A representative sample better reflects the population, reducing selection bias in estimates.")
]},
{id:"universal-technology",title:"Computing & Digital Technology",subject:"Technology",description:"Computer systems, the internet, programming, data, AI, privacy and cybersecurity.",cost:20,lessons:[
lesson("How computers represent information","Hardware, binary, memory, processors and operating systems.","A computer system combines hardware and software. The processor executes instructions; memory holds data currently in use; storage retains data when power is off; input and output devices connect the system to people and other machines. The operating system manages resources and provides services to applications.\n\nDigital systems represent information using bits, each with value 0 or 1. Groups of bits encode numbers, text, images and sound according to agreed formats. A byte contains eight bits. More bits can represent more distinct states, but the meaning depends on the encoding. Understanding representation explains why file formats, compression, resolution and compatibility matter.",["Identify the roles of CPU, memory and storage","Explain bits, bytes and encoding","Distinguish operating systems from applications"],"What is the smallest basic unit of digital information?",["Byte","Bit","Pixel","Hertz"],1,"A bit represents one binary digit, 0 or 1.") ,
lesson("Networks, the web and the internet","Packets, IP addresses, DNS, protocols and web architecture.","The internet is a network of interconnected networks. Data is commonly divided into packets that travel across routers and are reassembled at the destination. IP addresses identify network interfaces; DNS translates human-readable domain names into addresses. Protocols define how devices communicate.\n\nThe web is a service that runs over the internet. A browser requests resources from servers, commonly using HTTP or its encrypted form HTTPS. URLs identify resources. Client-server architecture separates the user-facing client from services and data hosted on servers. Reliability depends on routing, redundancy, security and correctly configured systems—not on a single central computer.",["Distinguish the internet from the World Wide Web","Describe packets, routing and DNS","Explain the role of HTTPS"],"What does DNS primarily do?",["Encrypts every file","Maps domain names to IP addresses","Creates computer hardware","Stores browser passwords"],1,"DNS resolves human-readable domain names to the network addresses needed for communication.") ,
lesson("Algorithms, programming and data","Stepwise problem solving, control flow, testing and data structures.","An algorithm is a finite, ordered method for solving a problem. A program expresses an algorithm in a language a computer can execute. Core control structures are sequence, selection (decisions) and iteration (repetition). Variables store values; functions package reusable behaviour.\n\nGood problem solving begins by defining inputs, outputs and constraints, then decomposing the task. Trace examples by hand, test normal and boundary cases, and use clear error messages. Data structures organise information: arrays or lists preserve sequences, maps associate keys with values, and sets represent unique members. Choose structures based on the operations the program needs.",["Describe sequence, selection and iteration","Break problems into smaller steps","Explain testing and basic data structures"],"Which control structure repeats a block of instructions?",["Sequence","Iteration","Selection","Declaration"],1,"Iteration repeats instructions while a condition holds or for a defined number of steps.") ,
lesson("AI, cybersecurity and digital responsibility","Machine learning, threat models, privacy and ethical design.","Artificial intelligence describes systems that perform tasks associated with human intelligence. Many modern systems use machine learning: a model learns patterns from training data and applies them to new inputs. Performance depends on data quality, task definition and evaluation. Models can make mistakes, reproduce bias or appear confident without being correct; outputs need independent checking.\n\nCybersecurity protects confidentiality, integrity and availability. Common threats include phishing, credential theft, malware and social engineering. Use unique passwords with a password manager, multifactor authentication, software updates and cautious link handling. Privacy requires collecting only necessary data, explaining its use, limiting access and respecting consent. Responsible technology also considers accessibility, fairness and environmental cost.",["Distinguish AI, machine learning and training data","Recognise common cyber threats and safeguards","Evaluate privacy, bias and responsible use"],"What is a strong defence against password reuse?",["Use one memorable password everywhere","Use unique passwords and multifactor authentication","Share passwords with trusted strangers","Disable software updates"],1,"Unique passwords limit the damage from a breach; multifactor authentication adds another barrier.")
]},
{id:"universal-health",title:"Human Body, Health & Wellbeing",subject:"Health science",description:"Anatomy, physiology, nutrition, movement, sleep, prevention and health literacy.",cost:20,lessons:[
lesson("Cells, organs and homeostasis","Body organisation and the systems that maintain internal balance.","The human body is organised into cells, tissues, organs and organ systems. Cells specialise for different tasks but depend on stable internal conditions. Homeostasis is the regulation of variables such as temperature, blood glucose, water balance and pH within workable ranges. It usually involves receptors detecting change, control centres processing information and effectors producing a response.\n\nThe circulatory system transports oxygen, nutrients, hormones and waste products. The respiratory system exchanges oxygen and carbon dioxide. The digestive system breaks food into absorbable molecules; the kidneys regulate water, salts and waste. These systems interact: no organ works in isolation. Understanding normal function helps make sense of symptoms and medical explanations.",["Describe levels of body organisation","Explain negative feedback and homeostasis","Summarise how major body systems cooperate"],"What is the main purpose of homeostasis?",["Keep every body variable absolutely fixed","Maintain internal conditions within healthy limits","Stop all changes in the body","Replace the immune system"],1,"Homeostasis adjusts internal conditions around suitable ranges despite internal and external changes.") ,
lesson("Nutrition and energy balance","Macronutrients, micronutrients, hydration and food literacy.","Food supplies energy and materials. Carbohydrates and fats are major energy sources; proteins provide amino acids for building and repair. Vitamins and minerals support processes such as bone health, nerve function and metabolism, while fibre supports digestive health. Water is essential for transport, temperature regulation and chemical reactions.\n\nNutritional needs vary with age, activity, health, culture and access to food. A balanced dietary pattern is more useful than judging one meal or a single nutrient. Food labels can help compare serving sizes, ingredients, added sugars, sodium and fibre. Be cautious of extreme diets and claims that promise rapid results; health decisions should rely on credible evidence and qualified care when needed.",["Describe roles of macronutrients and micronutrients","Explain hydration and fibre","Interpret food information without oversimplifying"],"Which statement about nutrition is most accurate?",["One food determines overall health","A balanced dietary pattern matters more than a single meal","All carbohydrates should be eliminated","Supplements replace all foods"],1,"Overall patterns across time provide a more useful picture than any one food or meal.") ,
lesson("Movement, sleep and recovery","Physical activity, adaptation, rest and sustainable habits.","Movement supports cardiovascular fitness, muscular strength, mobility, balance and mental wellbeing. Different activities train different capacities: aerobic activity challenges the heart and lungs over time, while resistance exercise loads muscles and bones. Progress should be gradual, appropriate to ability and balanced with recovery.\n\nSleep supports attention, memory, emotional regulation, immune function and tissue repair. Consistent sleep and wake times, a comfortable dark environment and a calming wind-down routine can help. Recovery is part of training: persistent pain, unusual fatigue or declining performance can signal that load needs adjustment. Sustainable habits are safer and more effective than sudden extreme routines.",["Distinguish aerobic, strength and mobility activity","Explain why sleep and recovery matter","Plan gradual, sustainable behaviour changes"],"Why is recovery important after challenging exercise?",["Adaptation occurs only during exercise","Recovery supports repair and adaptation","Rest always reduces fitness","Sleep has no effect on performance"],1,"Training provides a stimulus; recovery allows the body to repair and adapt to it.") ,
lesson("Prevention and health evidence","Infection control, screening, risk, reliable sources and care decisions.","Prevention includes vaccination where recommended, hand hygiene, safe food handling, adequate sleep, physical activity and reducing exposure to known risks. Screening looks for signs of disease before symptoms appear; whether a screening test is useful depends on accuracy, disease prevalence, benefits and possible harms.\n\nHealth claims should be assessed by asking who produced the evidence, how the study was designed, how many people were included, whether results were replicated and whether the findings apply to the person or population in question. A single anecdote or dramatic headline is weak evidence. For symptoms, diagnosis or treatment decisions, consult a qualified health professional rather than relying on a course or online self-diagnosis.",["Identify practical prevention strategies","Explain the purpose and limits of screening","Evaluate health claims and seek appropriate care"],"Which is the strongest basis for a health decision?",["A viral post","A single personal anecdote","Relevant high-quality evidence and qualified clinical advice","A product advertisement"],2,"Reliable decisions combine relevant research evidence with professional assessment and individual circumstances.")
]},
{id:"universal-psychology",title:"Psychology & Human Behaviour",subject:"Psychology",description:"Cognition, memory, emotion, motivation, personality, relationships and society.",cost:20,lessons:[
lesson("The brain, perception and attention","How sensory information is selected and interpreted.","Psychology studies behaviour and mental processes using systematic methods. The brain receives signals from sensory systems, but perception is not a simple recording of the world: the brain organises information using context, prior experience and expectations. Attention selects some information for deeper processing, so people can miss events that are visible but not attended to.\n\nDifferent brain networks contribute to perception, movement, language, emotion and memory. No single brain region explains complex behaviour on its own. Psychological explanations should connect biological processes with learning, development and social context, and should avoid treating simplified diagrams as complete accounts of the mind.",["Distinguish sensation from perception","Explain selective attention","Recognise limits of simple brain-region explanations"],"Why can a person miss an obvious event?",["Attention is selective","The eyes stop receiving light","Memory stores every detail equally","Perception is always objective"],0,"Attention has limited capacity; information outside its focus may not be consciously processed.") ,
lesson("Learning, memory and habit","Encoding, storage, retrieval, reinforcement and practice.","Learning is a relatively lasting change in knowledge or behaviour. Classical conditioning links stimuli; operant conditioning links behaviour with consequences. Reinforcement makes a behaviour more likely, while punishment aims to reduce it. The effect depends on timing, consistency and context.\n\nMemory involves encoding, storage and retrieval. Retrieval practice—trying to recall information—strengthens learning more effectively than repeatedly rereading alone. Spaced practice revisits material over time, helping reduce forgetting. Habits become easier when a consistent cue is linked to a small repeatable action and a meaningful reward. Sleep and attention influence memory formation.",["Compare classical and operant conditioning","Describe encoding, storage and retrieval","Apply retrieval practice and spacing"],"Which study method actively strengthens retrieval?",["Rereading without testing","Trying to recall the answer before checking notes","Highlighting every sentence","Studying once only"],1,"Retrieval practice requires bringing information to mind, strengthening access to it.") ,
lesson("Emotion, motivation and decisions","Needs, goals, cognitive biases and self-regulation.","Emotions combine bodily responses, appraisals, feelings and action tendencies. They can provide useful information but do not always give a complete or accurate interpretation of a situation. Motivation concerns processes that initiate and sustain goal-directed behaviour; it can be influenced by needs, values, expectations, rewards and perceived ability.\n\nDecision-making uses limited time and information. Heuristics are mental shortcuts that can be efficient but sometimes produce biases, such as anchoring on the first number heard or overestimating memorable risks. Better decisions separate facts from assumptions, consider alternatives, estimate consequences and pause when emotion or pressure is high.",["Describe components of emotional experience","Identify intrinsic and extrinsic motivation","Recognise common decision biases"],"What is anchoring bias?",["Changing a view after careful evidence","Relying too heavily on an initial piece of information","Forgetting every past experience","Choosing randomly"],1,"An initial value or impression can influence later judgement more than it deserves.") ,
lesson("Personality, relationships and social influence","Individual differences, groups, empathy and wellbeing.","Personality describes relatively enduring patterns in thinking, feeling and behaving. Traits can help describe differences, but they do not determine every action. Behaviour also depends on situation, culture, relationships and current goals. Psychological findings describe patterns across groups and should not be used to label or diagnose someone casually.\n\nSocial psychology examines how people influence one another. Norms shape what seems acceptable; conformity can support cooperation but can also suppress independent judgement. Healthy communication uses listening, clear boundaries and perspective-taking. Wellbeing is multi-dimensional and can be supported by relationships, meaningful activity, adequate rest and access to professional help when distress is persistent or severe.",["Explain traits and situational influences","Describe norms and conformity","Identify foundations of healthy communication and wellbeing"],"Why should personality traits not be treated as a complete prediction of behaviour?",["Situations and context also influence behaviour","Traits never show patterns","People cannot learn","All behaviour is random"],0,"Traits describe tendencies, while context and goals also shape what a person does.")
]},
{id:"universal-humanities",title:"History, Civilisations & Society",subject:"Humanities",description:"World history, cultures, political systems, social change and historical thinking.",cost:25,lessons:[
lesson("How historians know the past","Sources, chronology, context, corroboration and interpretation.","History is the study of change and continuity over time using evidence. Primary sources were produced during the period being studied, such as letters, tools, laws or photographs. Secondary sources interpret evidence after the event. Neither type is automatically reliable: authors have purposes, audiences, limitations and perspectives.\n\nHistorians establish chronology, place evidence in context and compare independent sources. Corroboration means checking whether different sources support or challenge a claim. Archaeology, environmental evidence, oral histories and written records can complement one another. A responsible account distinguishes what is well supported from what remains uncertain.",["Distinguish primary and secondary sources","Explain context and corroboration","Recognise bias and historical uncertainty"],"What does corroborating sources mean?",["Copying one account repeatedly","Comparing independent evidence to test a claim","Ignoring conflicting evidence","Assuming every source is neutral"],1,"Independent sources can strengthen or challenge an interpretation when compared carefully.") ,
lesson("Early societies and ancient civilisations","Agriculture, cities, states, writing and exchange.","The transition to agriculture changed how many communities obtained food, settled and organised labour. Surpluses could support specialised occupations, larger settlements and new forms of administration, although outcomes varied by region. Rivers, soils, climate and trade routes influenced where cities developed.\n\nAncient civilisations developed diverse systems of government, law, writing, religion, technology and social hierarchy. Their achievements should be studied alongside inequality, conflict and environmental pressures. Rather than treating history as a single ladder of progress, compare societies in their own contexts and examine how people adapted to local conditions.",["Explain links between agriculture and settlement","Identify features of complex societies","Compare civilisations without assuming one universal path"],"Why could agricultural surplus support larger settlements?",["It removed the need for cooperation","It allowed some people to specialise beyond food production","It ended environmental change","It made trade unnecessary"],1,"When fewer people can produce enough food, others may specialise in crafts, administration and exchange.") ,
lesson("Trade, belief and empire","Networks, cultural exchange, power and historical change.","Trade networks move goods, technologies, ideas, languages and diseases. Merchants and travellers connect distant regions, while ports and routes can become centres of wealth and cultural exchange. Belief systems shape institutions, art, law and identity, but are interpreted differently across communities and periods.\n\nEmpires extend authority over diverse territories through military power, alliances, administration and economic systems. Imperial rule can build infrastructure and connect regions while also involving coercion, extraction and resistance. Historical analysis asks who benefited, who bore the costs and how local people shaped events rather than viewing them as passive recipients of change.",["Describe how trade spreads ideas and technologies","Analyse methods of imperial control","Include local agency and unequal consequences"],"A balanced study of empire should examine:",["Only the ruler's achievements","Only one modern judgement","Power, exchange, resistance and effects on different groups","Events without evidence"],2,"Empires affect groups differently; analysis should examine power and consequences from multiple perspectives.") ,
lesson("Industrialisation and the modern world","Technological change, colonialism, conflict and global interdependence.","Industrialisation transformed production through mechanisation, fossil fuels, factories, transport and new financial systems. It increased output and changed work and urban life, but also produced harsh labour conditions, pollution and unequal gains. These changes were connected to global trade and colonial extraction.\n\nThe modern world was shaped by nationalism, imperial competition, world wars, decolonisation, ideological conflict, technological change and international institutions. Avoid explaining enormous events through a single cause: political decisions, economic pressures, social movements and long-term structures interact. Historical comparison helps reveal both recurring patterns and distinctive circumstances.",["Explain major effects of industrialisation","Connect imperialism and global economic systems","Analyse modern events through multiple causes"],"Why do historians usually explain major events using multiple causes?",["Because evidence is never useful","Because political, economic and social factors interact","Because chronology does not matter","Because one cause is always hidden"],1,"Complex events usually emerge from interacting conditions and decisions, not a single isolated factor.")
]},
{id:"universal-philosophy",title:"Philosophy, Logic & Ethics",subject:"Philosophy",description:"Critical thinking, knowledge, reality, morality, justice and responsible decisions.",cost:25,lessons:[
lesson("Arguments and critical thinking","Claims, premises, conclusions, validity and soundness.","An argument gives reasons (premises) in support of a conclusion. First identify the conclusion, then ask whether the premises are relevant and whether they provide enough support. A deductively valid argument is one where the conclusion must follow if the premises are true. A sound argument is valid and has true premises. Inductive arguments support conclusions with probability rather than certainty.\n\nCritical thinking is not automatic disagreement. It means interpreting claims fairly, checking evidence, identifying assumptions and considering counterexamples. Common errors include attacking the person instead of the argument, presenting a false dilemma and treating sequence as proof of causation.",["Identify premises and conclusions","Distinguish validity from soundness","Recognise common reasoning errors"],"What makes a deductive argument valid?",["Its conclusion is popular","If its premises are true, its conclusion must be true","Its speaker is confident","It contains many examples"],1,"Validity concerns the logical relationship between premises and conclusion, not popularity or confidence.") ,
lesson("Knowledge, reality and identity","Epistemology, scepticism, evidence and personal identity.","Epistemology asks what knowledge is and how beliefs can be justified. A belief may be true by luck without amounting to knowledge, so philosophers examine evidence, reliability and justification. Perception, memory, testimony and reasoning are important sources of belief, each with possible limitations.\n\nMetaphysics investigates questions about what exists, causation, time, mind and personal identity. Thought experiments test intuitions by changing one feature of a case. They do not settle questions by themselves; their value lies in clarifying assumptions and revealing tensions between principles.",["Explain the difference between belief and knowledge","Evaluate sources of justification","Use thought experiments to clarify assumptions"],"Why is a true belief not automatically knowledge?",["Truth is irrelevant","It may be true by luck without adequate justification","Knowledge never uses evidence","All beliefs are false"],1,"Many accounts require more than truth: the belief must be appropriately justified or reliably formed.") ,
lesson("Ethical frameworks and moral reasoning","Consequences, duties, virtues, rights and moral dilemmas.","Ethics asks how people ought to act and what makes actions, institutions or lives good. Consequentialist approaches assess outcomes; deontological approaches emphasise duties and principles; virtue ethics focuses on character and practical wisdom. Each framework highlights important considerations and faces difficult cases.\n\nA careful moral analysis identifies stakeholders, possible harms and benefits, rights, duties, fairness and relevant context. It distinguishes facts from value judgements and considers whether a principle can be applied consistently. Real dilemmas may involve competing legitimate values, so transparent reasoning is more useful than pretending every case has an effortless answer.",["Compare three major ethical approaches","Identify stakeholders and competing values","Construct a reasoned ethical judgement"],"Which approach focuses primarily on character and virtues?",["Consequentialism","Virtue ethics","Pure cost accounting","Logical positivism"],1,"Virtue ethics asks what a good person would characteristically do and which traits support flourishing.") ,
lesson("Justice, rights and applied philosophy","Equality, liberty, institutions and public reasoning.","Political philosophy examines authority, freedom, equality, rights and the responsibilities of institutions. Equality can mean equal treatment, equal opportunity or attention to unequal starting conditions. Liberty can involve freedom from interference and the practical ability to pursue meaningful choices. These values can conflict and require careful argument.\n\nApplied philosophy brings concepts into real decisions about technology, environment, education, work and public policy. Ask who has power, who is affected, which rights are at stake, what evidence is available and whether the rule would remain acceptable if roles were reversed. Good public reasoning makes assumptions visible and treats opposing arguments seriously.",["Distinguish forms of equality and liberty","Analyse rights and institutional responsibilities","Apply principles consistently to real cases"],"A useful test of a proposed rule is to ask:",["Whether it benefits only its author","Whether it would remain fair if roles were reversed","Whether it avoids all disagreement","Whether it sounds complicated"],1,"Role reversal helps reveal whether a rule depends on unfairly favouring one's own position.")
]},
{id:"universal-economics",title:"Economics & Personal Finance",subject:"Business",description:"Markets, incentives, money, banking, budgeting, saving, investing and risk.",cost:25,lessons:[
lesson("Scarcity, choice and markets","Opportunity cost, incentives, supply, demand and competition.","Economics studies how people and societies make choices when resources are limited. Scarcity means not every want can be satisfied; choosing one option creates an opportunity cost—the value of the next-best alternative given up. Incentives influence decisions, but people also act from habits, norms and imperfect information.\n\nIn a basic competitive market, demand generally describes how much buyers are willing and able to purchase at different prices; supply describes how much sellers are willing and able to offer. Equilibrium is where planned quantity supplied equals quantity demanded. Real markets can include market power, externalities, information gaps and regulation, so the simple model is a starting point rather than a universal description.",["Define scarcity and opportunity cost","Explain supply, demand and equilibrium","Identify limitations of simplified market models"],"What is opportunity cost?",["The total money ever earned","The value of the next-best alternative forgone","A tax on every purchase","The same as market price"],1,"Opportunity cost measures the best alternative sacrificed by a choice.") ,
lesson("Budgeting, banking and interest","Cash flow, emergency funds, borrowing and compound interest.","A budget compares expected income with planned spending and saving over a period. Tracking actual cash flow reveals patterns and helps distinguish needs, wants, fixed costs and variable costs. An emergency fund can reduce the need to borrow when an unexpected expense occurs. The right amount depends on circumstances and access to support.\n\nBanks provide services such as deposits, payments and lending. Interest is the cost of borrowing or the return paid on savings. Compound interest means interest is earned on prior interest as well as the original amount, so time and rate both matter. Compare fees, repayment terms and effective costs; never share PINs, one-time passwords or banking credentials.",["Build a simple income-and-expense budget","Explain simple and compound interest","Recognise safe banking practices"],"Why can compound interest grow faster than simple interest?",["It earns interest on accumulated interest","It removes all risk","It always has a higher rate","It ignores time"],0,"Compounding adds prior interest to the balance on which future interest is calculated.") ,
lesson("Saving, investing and risk","Asset classes, diversification, time horizon and uncertainty.","Saving usually prioritises access and stability; investing accepts uncertainty in pursuit of longer-term returns. Common assets include deposits, bonds, shares and diversified funds, each with different risks, costs and liquidity. A higher potential return usually comes with some form of additional risk; returns are not guaranteed.\n\nDiversification spreads exposure across different investments, reducing dependence on one company or asset, though it cannot remove market-wide risk. A suitable plan considers goals, time horizon, emergency savings, ability to tolerate losses, fees and taxes. Avoid decisions based only on social-media tips, guaranteed-return promises or fear of missing out.",["Distinguish saving from investing","Explain diversification and risk","Relate investment choices to goals and time horizon"],"What does diversification mainly aim to do?",["Guarantee profits","Reduce dependence on a single investment","Eliminate every possible loss","Predict tomorrow's price"],1,"Diversification can reduce concentration risk but cannot guarantee returns or remove all risk.") ,
lesson("Financial safety and informed decisions","Fraud, consumer rights, insurance and evaluating advice.","Financial safety includes protecting identity information, verifying payment requests and checking official channels before acting. Common scams use urgency, impersonation, fake investment returns or requests for OTPs and remote access. Pause, independently verify the person or organisation and report suspicious activity through official routes.\n\nInsurance transfers specified financial risks in exchange for a premium, subject to exclusions and conditions. Read what is covered, limits, waiting periods and claim requirements. Compare financial products using total costs, liquidity, risk and regulation—not advertising alone. For complex or high-stakes decisions, seek appropriately qualified, independent advice and understand that all investments carry risk.",["Recognise common financial scams","Explain the purpose and limits of insurance","Evaluate financial claims and advice"],"Someone asks for your banking OTP to release a prize. What should you do?",["Share it quickly","Refuse and verify through official channels","Send a small fee first","Install their remote-access app"],1,"Legitimate providers should not ask you to disclose an OTP; independently verify and report suspicious requests.")
]},
{id:"universal-business",title:"Business & Entrepreneurship",subject:"Business",description:"Customer research, value propositions, business models, pricing, marketing and operations.",cost:30,lessons:[
lesson("Find a real customer problem","Observation, interviews, segmentation and problem validation.","A business creates value by solving a problem for a specific group of customers. Begin by describing the customer, the situation and the difficulty they experience. Separate observed behaviour from assumptions. Interviews are most useful when questions invite stories about past behaviour rather than asking whether someone likes your idea.\n\nSegment a broad market into groups with shared needs or circumstances. Look for evidence that the problem is frequent, painful and important enough that people already spend time or money addressing it. A problem statement should be specific and testable. Do not build a full product before learning whether the problem is real.",["Write a clear customer problem statement","Use interviews to learn about actual behaviour","Identify and test assumptions"],"Which interview question gives stronger evidence?",["Would you buy my idea?","Tell me about the last time you faced this problem","Do you think my logo is attractive?","Would you say yes to support me?"],1,"A recent real example reveals behaviour and current workarounds rather than hypothetical enthusiasm.") ,
lesson("Value propositions and business models","Customer value, channels, revenue, costs and unit economics.","A value proposition explains who a product serves, what problem it solves and why the solution is useful compared with alternatives. A business model describes how an organisation creates, delivers and captures value. It includes customer segments, channels, relationships, key activities, partners, resources, revenue streams and cost structure.\n\nUnit economics examines the revenue and variable cost associated with one sale or customer. Contribution per unit is selling price minus variable cost. Fixed costs must still be covered before a business becomes profitable. A model is a set of hypotheses: test willingness to pay, delivery costs and repeat use with small experiments before scaling.",["State a customer-centred value proposition","Map the main parts of a business model","Calculate contribution and identify fixed costs"],"If a product sells for ₹500 and variable cost is ₹300, contribution per unit is:",["₹100","₹200","₹300","₹800"],1,"Contribution is selling price minus variable cost: ₹500 − ₹300 = ₹200.") ,
lesson("Pricing, marketing and sales","Positioning, channels, trust and conversion.","Pricing communicates value and affects demand, revenue and margin. Cost-based pricing starts with costs and a margin; value-based pricing considers customer-perceived benefits; competitor-based pricing uses market alternatives as a reference. No method removes the need to test how real customers respond.\n\nMarketing helps the right audience discover and understand an offer. Positioning clarifies the intended customer and distinctive benefit. Choose channels based on where customers actually pay attention, then measure useful outcomes such as qualified enquiries, conversion, retention and customer acquisition cost. Honest claims, clear terms and responsive support build trust more sustainably than manipulation.",["Compare common pricing approaches","Describe positioning and channel selection","Choose meaningful marketing metrics"],"Which metric measures the share of visitors who complete a desired action?",["Conversion rate","Inventory age","Gross weight","Office rent"],0,"Conversion rate measures completed desired actions relative to the relevant audience or visits.") ,
lesson("Operations, cash flow and responsible growth","Delivery systems, quality, records and scaling decisions.","Operations turn a promise into a consistent customer experience. Map the steps from order to delivery, identify bottlenecks and define quality standards. Keep accurate records of sales, costs, inventory, refunds and cash movements. Profit and cash flow are different: a business can show accounting profit while lacking cash to pay bills on time.\n\nGrowth increases complexity. Before expanding, check that demand is repeatable, delivery quality is stable, unit economics make sense and working capital is sufficient. Treat customer data responsibly, follow applicable laws and build fair practices for workers and suppliers. Sustainable growth comes from learning and improving systems, not simply increasing activity or spending.",["Map a simple delivery process","Distinguish profit from cash flow","Identify readiness checks before scaling"],"Why can a profitable business still run out of cash?",["Profit and cash timing differ; bills may be due before cash arrives","Profit always equals bank balance","Cash flow matters only to large firms","Sales remove all expenses"],0,"Timing of customer payments, inventory and bills can create a cash shortage even when recorded sales exceed costs.")
]},
{id:"universal-communication",title:"Communication, Language & Writing",subject:"Practical skills",description:"Clear communication, active listening, writing, research, presentations and persuasion.",cost:20,lessons:[
lesson("Purpose, audience and active listening","Clarity, context, questions and feedback.","Effective communication begins with purpose: inform, ask, explain, coordinate or persuade. The audience affects vocabulary, detail, tone and format. A clear message places the main point early and organises supporting details in a logical order. Remove ambiguity where it could cause mistakes.\n\nActive listening means giving attention, checking understanding and asking open questions rather than preparing a reply while the other person speaks. Paraphrase important points, distinguish facts from interpretations and invite correction. Non-verbal signals can add context, but they vary across people and cultures; do not assume one gesture has a universal meaning.",["Match message to purpose and audience","Use paraphrasing and open questions","Check understanding and reduce ambiguity"],"What is a useful active-listening response?",["Interrupt with advice immediately","Paraphrase the speaker's point and check if you understood","Change the subject","Assume silence means agreement"],1,"Paraphrasing makes understanding visible and gives the speaker a chance to correct it.") ,
lesson("Writing, research and source evaluation","Structure, evidence, citations and revision.","Strong writing has a clear purpose, a logical structure and evidence suited to its claims. A paragraph often develops one main idea: state the point, explain it, support it with evidence and connect it to the larger argument. Drafting and editing are different tasks; first develop ideas, then revise structure, clarity, accuracy and grammar.\n\nResearch begins with a focused question. Evaluate sources by expertise, evidence, publication process, date, purpose and possible conflicts of interest. Cross-check important claims with independent sources. Keep accurate notes and cite ideas, data and quotations so readers can trace them. Never present another person's work as your own.",["Structure paragraphs around one main idea","Evaluate credibility and relevance of sources","Use citations and ethical paraphrasing"],"Why cite a source?",["To make writing look longer","To let readers trace evidence and acknowledge original work","To avoid checking the source","To guarantee the claim is true"],1,"Citations support transparency and attribution, though a cited claim still needs evaluation.") ,
lesson("Speaking and presentations","Narrative, visual design, rehearsal and delivery.","A presentation should guide an audience through a small number of connected ideas. Start with the question or problem, explain why it matters, develop the evidence and end with a clear conclusion or action. Signpost transitions so listeners know where they are. Rehearse aloud and time the delivery.\n\nSlides should support the speaker rather than duplicate a script. Use readable text, meaningful visuals and labelled charts. Explain what a chart measures, its units and the main pattern; do not distort axes or omit context. Speak at a measured pace, pause after important points and adapt to audience questions without pretending to know what you do not.",["Organise a clear presentation narrative","Design readable, honest visual aids","Rehearse and respond to questions"],"What should a chart in a presentation include?",["Only decorative colours","Clear labels, units and relevant context","A hidden scale","As many effects as possible"],1,"Labels and units let the audience interpret the data accurately.") ,
lesson("Persuasion, negotiation and digital communication","Claims, evidence, empathy and professional conduct.","Ethical persuasion connects a clear claim to relevant evidence and acknowledges important limitations. It considers the audience's concerns without exploiting fear, false urgency or misleading statistics. Negotiation works best when people understand interests beneath stated positions and look for options that address legitimate needs.\n\nDigital messages lack many cues available in face-to-face conversation. Use descriptive subject lines, concise paragraphs and an appropriate tone. Before sharing information, verify accuracy, privacy and permission. Written records can be forwarded or misunderstood, so pause before sending emotionally charged messages and correct errors transparently.",["Build claims supported by evidence","Distinguish interests from positions in negotiation","Communicate responsibly online"],"Which is an example of ethical persuasion?",["Hiding important risks","Using relevant evidence and disclosing limitations","Inventing a deadline","Misquoting an opponent"],1,"Ethical persuasion respects the audience's ability to make an informed decision.")
]},
{id:"universal-creative",title:"Arts, Culture & Creative Practice",subject:"Creative arts",description:"Visual design, music, literature, cultural interpretation and creative process.",cost:20,lessons:[
lesson("Visual elements and design principles","Line, shape, colour, contrast, hierarchy and composition.","Visual communication uses elements such as line, shape, form, colour, texture, space and value. Principles such as contrast, balance, alignment, repetition, proximity and hierarchy organise those elements. A focal point helps viewers understand where to look first. White space is active space that can improve clarity rather than wasted area.\n\nColour relationships can create emphasis and mood, but meaning varies by context and culture. Accessibility matters: do not rely on colour alone to communicate status, and maintain sufficient contrast for text. A design should be judged against its purpose and audience, not only whether it looks fashionable.",["Identify core visual elements","Apply hierarchy, contrast and alignment","Consider accessibility and audience"],"What does visual hierarchy help communicate?",["Which information should be noticed first","The file size","The artist's age","The printing cost"],0,"Hierarchy guides attention by making the relative importance of information clear.") ,
lesson("Music, literature and cultural context","Form, rhythm, narrative, genre and interpretation.","Artworks are shaped by choices of form, materials, technique and context. In music, rhythm organises time, melody shapes pitch movement and harmony relates simultaneous pitches. In literature, narrative voice, imagery, structure and genre influence how readers interpret a text. These features can be analysed without assuming there is only one valid response.\n\nCulture and historical context affect how works are made, circulated and understood. Interpretation should be supported by details in the work and relevant context. Avoid reducing a tradition to stereotypes or treating one culture's standards as universal. Listening and reading across traditions expands the range of artistic forms we can recognise.",["Recognise basic musical and literary elements","Connect works with context","Support interpretations with evidence from the work"],"A well-supported interpretation should:",["Ignore the artwork itself","Use details from the work and relevant context","Assume every audience responds identically","Rely only on popularity"],1,"Interpretation becomes stronger when grounded in observable features and context.") ,
lesson("The creative process and experimentation","Research, ideation, prototypes, feedback and iteration.","Creative work often moves through research, idea generation, selection, making, feedback and revision. The process is rarely perfectly linear: making something reveals questions that planning alone cannot answer. Generate several alternatives before committing, and use small prototypes to test composition, usability or meaning.\n\nFeedback is most useful when it is specific, respectful and connected to the intended goal. Separate the work from personal worth. Decide which suggestions serve the purpose and explain why others may not. Keep versions or a process journal so that decisions and learning are visible. Constraints can support creativity by focusing attention on meaningful choices.",["Describe stages of an iterative creative process","Use prototypes to test ideas","Give and evaluate constructive feedback"],"Why create a prototype early?",["To avoid learning from users","To test an idea cheaply before investing heavily","To prove the first idea is perfect","To eliminate revision"],1,"A prototype reveals practical issues early, when changes are less costly.") ,
lesson("Art, society and creative responsibility","Representation, ownership, interpretation and impact.","Art can preserve memory, question power, express identity, entertain and imagine alternatives. Works circulate within institutions and markets that influence which voices are seen and valued. Ask whose perspective is represented, who is absent, how audiences may interpret the work and what historical or social conditions shape it.\n\nCreative responsibility includes respecting intellectual property, crediting collaborators, obtaining permission where needed and considering the impact of representation. Inspiration is not the same as copying. Transformative practice develops ideas through new choices and context while acknowledging sources and respecting communities.",["Analyse art's social roles","Consider representation and audience","Respect attribution, permission and creative ownership"],"What is a responsible way to use another creator's work?",["Remove their name","Credit the creator and follow permission or licence terms","Assume everything online is free to copy","Claim it as original"],1,"Attribution and licence or permission terms help respect creators' rights.")
]},
{id:"universal-environment",title:"Earth, Geography & Sustainability",subject:"Science",description:"Maps, climate, ecosystems, biodiversity, resources, energy and sustainability.",cost:25,lessons:[
lesson("Maps, landforms and Earth's systems","Scale, coordinates, water, weather and physical geography.","Geography studies places, spatial relationships and interactions between people and environments. Maps simplify the world for particular purposes. Scale connects map distance to ground distance; coordinates locate places; symbols and legends explain what is shown. Every map involves choices about projection, detail and emphasis, so no map is a perfectly neutral copy of Earth.\n\nEarth systems include the atmosphere, hydrosphere, geosphere and biosphere. Weather describes short-term atmospheric conditions; climate describes patterns over longer periods. Water moves through evaporation, condensation, precipitation, infiltration and runoff. Landforms reflect processes such as tectonic movement, erosion, deposition and volcanism.",["Interpret scale, coordinates and map legends","Distinguish weather from climate","Describe interactions among Earth systems"],"What is the difference between weather and climate?",["They are identical","Weather is short-term conditions; climate is long-term patterns","Climate changes every hour","Weather describes only temperature"],1,"Climate summarises long-term patterns and variability, while weather is the state of the atmosphere at a particular time.") ,
lesson("Climate, biodiversity and ecosystems","Greenhouse effect, habitats, food webs and resilience.","The natural greenhouse effect keeps Earth warmer than it would otherwise be because certain gases absorb and re-emit infrared radiation. Human activities, especially burning fossil fuels and land-use change, increase greenhouse gas concentrations and strengthen warming. Climate change affects heat extremes, rainfall patterns, sea level and ecosystems, with impacts varying by region.\n\nBiodiversity includes variation within species, between species and among ecosystems. It supports food systems, pollination, soil formation, water regulation and cultural values. Habitat loss, pollution, invasive species, overexploitation and climate change can reduce biodiversity. Ecosystem resilience depends on diversity, connectivity and the ability to recover from disturbance.",["Explain the enhanced greenhouse effect","Describe levels and benefits of biodiversity","Identify major pressures on ecosystems"],"Which statement best describes the enhanced greenhouse effect?",["Greenhouse gases block all sunlight","Higher greenhouse gas concentrations increase heat retained in the climate system","The ozone hole causes all global warming","Weather and climate are the same"],1,"Additional greenhouse gases reduce the rate at which Earth loses energy to space, warming the system.") ,
lesson("Resources, energy and circular systems","Renewable resources, efficiency, extraction and waste.","Resources include materials, water, land and energy. Renewable sources can replenish on human timescales under suitable management, while non-renewable resources form much more slowly than they are consumed. Energy systems should be compared using reliability, cost, emissions, land and material needs, safety and impacts across their life cycle.\n\nA circular economy aims to reduce waste by designing products for durability, repair, reuse, remanufacture and recycling. Recycling is useful but usually requires energy and cannot recover every material perfectly. Reducing unnecessary consumption and extending product life can prevent impacts earlier in the resource chain.",["Compare renewable and non-renewable resources","Evaluate energy options across multiple impacts","Explain reduce, repair, reuse and recycling"],"Why is repair often valuable in a circular economy?",["It extends product life and can avoid new material demand","It always has zero environmental impact","It increases planned obsolescence","It removes the need for design"],0,"Keeping products useful can reduce demand for new resources and the waste associated with replacement.") ,
lesson("Sustainability, policy and collective action","Trade-offs, environmental justice and measurable change.","Sustainability considers environmental integrity, social wellbeing and economic conditions across generations. A decision may reduce emissions while affecting jobs, land use or energy access; good policy makes trade-offs visible and seeks fair outcomes. Environmental justice asks who receives benefits, who bears pollution or climate risks and who has a voice in decisions.\n\nProgress should be measured with clear indicators and baselines, such as emissions per unit of output, water use, habitat condition or access to clean energy. Individual actions matter, but infrastructure, institutions, technology and public policy shape what choices are possible. Effective solutions combine personal, community, business and government action.",["Explain the dimensions of sustainability","Analyse environmental justice and trade-offs","Choose indicators to evaluate progress"],"Why use a baseline when measuring sustainability progress?",["To hide changes","To compare later results against a defined starting point","To guarantee a positive result","To avoid collecting data"],1,"A baseline provides a reference for judging whether conditions have improved or worsened.")
]}
];

export function createUniversalKnowledgeCourses(now = new Date().toISOString()): KnowledgeCourse[] {
 const prerequisites: Record<string,string> = { "universal-technology":"universal-mathematics", "universal-health":"universal-science", "universal-psychology":"universal-science", "universal-environment":"universal-science", "universal-economics":"universal-mathematics", "universal-business":"universal-economics", "universal-philosophy":"universal-humanities", "universal-creative":"universal-humanities" };
 return seeds.map(seed => ({
  id:seed.id,title:seed.title,created:now,subject:seed.subject,level:"Foundation to Advanced",
  description:seed.description,
  objectives:["Understand core concepts and vocabulary","Apply principles to practical examples","Evaluate evidence, assumptions and limitations","Connect ideas across disciplines"],
  prerequisiteCourseId:prerequisites[seed.id] || "",unlockCost:seed.cost,unlocked:seed.cost===0 && !prerequisites[seed.id],done:false,updatedAt:now,
  lessons:seed.lessons.map((item,index)=>({
   id:seed.id+"-lesson-"+(index+1),title:item.title,summary:item.summary,content:item.content,
   objectives:item.objectives,estimatedMinutes:25+index*5,resources:[],
   question:{prompt:item.question,options:item.options,answerIndex:item.answer,explanation:item.explanation},
   done:false
  }))
 }));
}
